-- No pgTAP extension required. Every failed assertion raises and stops psql; all fixtures roll back.
begin;
create function pg_temp.eq(q text, expected bigint, label text) returns void language plpgsql as $$
declare actual bigint;
begin execute q into actual; if actual is distinct from expected then raise exception '%: expected %, got %',label,expected,actual; end if; raise notice 'PASS %',label; end $$;
create function pg_temp.denied(q text, expected text, label text) returns void language plpgsql as $$
begin
 begin execute q; exception when others then
 if sqlstate=expected then raise notice 'PASS %',label; return; end if; raise; end;
 raise exception '%: unexpectedly succeeded',label;
end $$;
create function pg_temp.affected(q text, expected bigint, label text) returns void language plpgsql as $$
declare actual bigint;
begin execute q; get diagnostics actual=row_count;
 if actual<>expected then raise exception '%: expected % affected, got %',label,expected,actual; end if;
 raise notice 'PASS %',label; end $$;

